"""Geometric native-pose and dexterous-hand controller, authored for this scene."""
import numpy as np
from scipy.spatial.transform import Rotation as Rot, Slerp

class Controller:
    def __init__(self, s):
        self.s=s
        self.m,self.d=s.model,s.data
        bid=self.m.body('robot0_base').id
        self.Rb=self.d.xmat[bid].reshape(3,3).copy()
        self.pb=self.d.xpos[bid].copy()
    def obj(self,name='obj'):
        return self.d.xpos[self.m.body(self.s.env.objects[name].root_body).id].copy()
    def hand(self,arm='right'):
        si=self.m.site('gripper0_'+arm+'_grip_site').id
        return self.d.site_xpos[si].copy(),self.d.site_xmat[si].reshape(3,3).copy()
    def move(self,p=None,R=None,g=None,n=50,arm='right'):
        k,gi=(0,12) if arm=='right' else (6,18)
        a0=self.s.targets.copy(); a1=a0.copy()
        if p is not None: a1[k:k+3]=self.Rb.T@(np.asarray(p)-self.pb)
        if R is not None: a1[k+3:k+6]=Rot.from_matrix(self.Rb.T@R).as_rotvec()
        if g is not None: a1[gi:gi+6]=g
        sl=Slerp([0,1],Rot.from_rotvec(np.stack([a0[k+3:k+6],a1[k+3:k+6]])))
        for t in np.linspace(0,1,n+1)[1:]:
            u=t*t*(3-2*t); a=a0+(a1-a0)*u; a[k+3:k+6]=sl(u).as_rotvec(); self.s.step(a)
    def hold(self,n):
        for _ in range(n): self.s.step(self.s.targets)
    def metrics(self):
        p,c=self.obj(),self.obj('container')
        ds={a:{'pepper':float(np.linalg.norm(self.hand(a)[0]-p)), 'pot':float(np.linalg.norm(self.hand(a)[0]-c))} for a in ['left','right']}
        return dict(success=self.s.check()['success'],steps=len(self.s.actions),pepper=p.tolist(),pot=c.tolist(),horizontal_error=float(np.linalg.norm(p[:2]-c[:2])),hand_distances=ds)

def trial(s, x=.012,y=-.073,z=.043,tf=1.2,tr=1.65, finger=1.6,release='all',release_z=1.18,speed=1.,correction=0.):
    c=Controller(s)
    def move(**kw):
        kw['n']=max(1,round(kw.get('n',50)*speed)); c.move(**kw)
    def hold(n): c.hold(max(1,round(n*speed)))
    p=c.obj(); Rd=np.diag([1.,-1.,-1.])
    move(p=[2.30,-1.96,1.24],n=50,arm='left')
    move(p=p+[x,y,.17],R=Rd,g=[0,0,0,0,1.,0],n=80)
    move(p=p+[x,y,z],n=60)
    move(p=p+[x,y+correction,z],g=[finger]*4+[tf,tr],n=70)
    hold(30)
    move(p=c.hand()[0]+[0,0,.18],n=90)
    hold(20)
    print('LIFT',c.obj().tolist(),flush=True)
    if c.obj()[2]<1.07: return c,'grasp_failed'
    off=c.obj()-c.hand()[0]; pot=c.obj('container')
    move(p=[c.hand()[0][0],c.hand()[0][1],1.27],n=35)
    move(p=[pot[0]-off[0],pot[1]-off[1],1.27],n=130)
    hold(20)
    print('TRANSFER',c.obj().tolist(),flush=True)
    if c.obj()[2]<1.1: return c,'transfer_failed'
    move(p=[pot[0]-off[0],pot[1]-off[1],release_z],n=60)
    if release=='all':
        move(g=np.zeros(6),n=45)
    elif release=='fingers':
        move(g=[0,0,0,0,tf,tr],n=45)
    elif release=='thumb':
        move(g=[finger]*4+[tf,0],n=30)
        move(g=np.zeros(6),n=30)
    hold(30)
    move(p=[2.91,-2.03,1.30],n=100)
    hold(40)
    print('END',c.metrics(),flush=True)
    return c,'complete'
